 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function SubscriptionPlanCards2() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Why Choose Lueora?</title>
    <link href="https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css" rel="stylesheet">
    <style>
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: #f0f8ff;
            line-height: 1.5;
        }

        .comparison-container {
            background: linear-gradient(to bottom, #ebf8ff, #ffffff);
        }

        .comparison-table th {
            background-color: #e3f2fd;
            color: #0369a1;
        }

        .comparison-table td {
            background-color: #ffffff;
        }

        .comparison-table .check {
            color: #10b981;
        }

        .comparison-table .cross {
            color: #ef4444;
        }

        .comparison-table tr:hover {
            background-color: #dbeafe;
            transition: background-color 0.3s;
        }

        .header-title {
            color: #1e3a8a;
        }

        .sub-title {
            color: #374151;
        }

        .brand-section {
            display: flex;
            align-items: center;
            justify-content: center;
            margin-top: 2rem;
        }

        .brand-logo {
            width: 60px;
            height: 60px;
        }

        .brand-title {
            margin-left: 0.75rem;
            font-size: 1.5rem;
            font-weight: 600;
            color: #1e90ff;
        }

        footer {
            padding: 1.5rem 0;
            font-size: 0.875rem;
            color: #6b7280;
        }
    </style>
</head>

<body class="comparison-container">

    <div class="min-h-screen flex flex-col justify-center items-center py-12 px-4 sm:px-6 lg:px-8">
        <div class="w-full max-w-6xl bg-white rounded-lg shadow-xl p-8 md:p-10">
            <h2 class="text-3xl font-bold text-center mt-12 sm:text-5xl header-title">Why Choose Lueora?</h2>
            <p class="max-w-3xl mx-auto mt-4 text-xl text-center sub-title">See how Lueora stands out from other brands.</p>

            <div class="mt-24 container space-y-12">
                <div class="relative p-8 border border-gray-200 rounded-2xl shadow-lg bg-white">
                    <table class="w-full text-left border-collapse comparison-table">
                        <thead>
                            <tr>
                                <th class="py-4 px-6 font-semibold text-lg">Feature</th>
                                <th class="py-4 px-6 font-semibold text-lg text-center">Lueora</th>
                                <th class="py-4 px-6 font-semibold text-lg text-center">Other Brands</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr class="border-b">
                                <td class="py-4 px-6">High Quality</td>
                                <td class="py-4 px-6 text-center check">✅</td>
                                <td class="py-4 px-6 text-center cross">❌</td>
                            </tr>
                            <tr class="border-b">
                                <td class="py-4 px-6">Health & Comfort Focused</td>
                                <td class="py-4 px-6 text-center check">✅</td>
                                <td class="py-4 px-6 text-center cross">❌</td>
                            </tr>
                            <tr class="border-b">
                                <td class="py-4 px-6">Fast & Free Shipping</td>
                                <td class="py-4 px-6 text-center check">✅</td>
                                <td class="py-4 px-6 text-center cross">❌</td>
                            </tr>
                            <tr class="border-b">
                                <td class="py-4 px-6">Hassle-Free Refunds</td>
                                <td class="py-4 px-6 text-center check">✅</td>
                                <td class="py-4 px-6 text-center cross">❌</td>
                            </tr>
                            <tr class="border-b">
                                <td class="py-4 px-6">Quick Email Support</td>
                                <td class="py-4 px-6 text-center check">✅</td>
                                <td class="py-4 px-6 text-center cross">❌</td>
                            </tr>
                            <tr>
                                <td class="py-4 px-6">Innovative Home Solutions</td>
                                <td class="py-4 px-6 text-center check">✅</td>
                                <td class="py-4 px-6 text-center cross">❌</td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    </div>

</body>

</html>" }} />
  );
}
